function bs(){bw=bc.width=innerWidth;bh=bc.height=innerHeight}bs();addEventListener('resize',bs);
function nb(x,y,burst){return{x:x==null?Math.random()*bw:x,y:y==null?Math.random()*bh:y,r:burst?4+Math.random()*9:10+Math.random()*34,vy:burst?-(1+Math.random()*2):-(.25+Math.random()*.5),vx:burst?(Math.random()-.5)*3:0,ph:Math.random()*6,a:burst?.7:.4,c:Math.random()<.5,burst:burst,life:burst?70:1e9}}
