function rl(){bx.clearRect(0,0,bw,bh);for(const r of RB){r.ph+=.035;r.x+=r.vx;r.y+=r.vy+Math.sin(r.ph)*.5;const dx=r.x-bm.x,dy=r.y-bm.y,d=Math.hypot(dx,dy);if(d<170&&d>0){r.vx+=dx/d*.2;r.vy+=dy/d*.2}const sp=Math.hypot(r.vx,r.vy);if(sp>2){r.vx*=.95;r.vy*=.95}else if(sp<.5){r.vx+=(Math.random()-.5)*.15;r.vy+=(Math.random()-.5)*.15}if(r.x<30||r.x>bw-30)r.vx*=-1;if(r.y<30||r.y>bh-30)r.vy*=-1;r.x=Math.max(20,Math.min(bw-20,r.x));r.y=Math.max(20,Math.min(bh-20,r.y));bx.save();bx.globalAlpha=.92;bx.translate(r.x,r.y);bx.rotate(Math.sin(r.ph)*.2+r.vx*.06);bx.scale(r.vx<0?-1:1,1);bx.drawImage(RI,-r.s/2,-r.s/2,r.s,r.s*RI.height/(RI.width||1));bx.restore()}requestAnimationFrame(rl)}
